-- The recipes table has existed since the initial schema and the whole Recipes
-- tab is built against it -- search, category filter, save, grocery-list export
-- and the detail screen. It was simply never seeded, so every member saw "No
-- recipes found" and the nutrition feature looked unbuilt.
--
-- 24 recipes across the six categories the UI offers. goal_tags use the same
-- vocabulary as the onboarding goals so recipes can be matched to a member's
-- objective; allergy_tags and dietary_tags drive the filters.
insert into public.recipes (
  id,
  title,
  description,
  category,
  goal_tags,
  dietary_tags,
  allergy_tags,
  prep_time_mins,
  cook_time_mins,
  servings,
  difficulty,
  calories,
  protein,
  carbs,
  fat,
  fiber,
  sodium,
  cost_per_serving,
  ingredients,
  instructions,
  storage_notes,
  reheat_notes,
  equipment,
  is_published
) values
  ('rc-b1', 'Protein Overnight Oats', 'Make it tonight, eat it cold tomorrow. Slow carbs and 32g of protein with no morning cooking.', 'Breakfast', array['Build Muscle', 'Improve Endurance', 'Improve Overall Fitness'], array['High Protein', 'Vegetarian'], array['Dairy', 'Gluten'], 10, 0, 1, 'Easy', 430, 32, 52, 10, 8, 180, 1.8, '[{"name": "Rolled oats", "amount": "1/2 cup", "substitutes": []}, {"name": "Greek yogurt", "amount": "3/4 cup", "substitutes": ["Skyr", "Cottage cheese"]}, {"name": "Whey protein, vanilla", "amount": "1 scoop", "substitutes": ["Casein protein"]}, {"name": "Milk", "amount": "1/2 cup", "substitutes": ["Almond milk", "Oat milk"]}, {"name": "Chia seeds", "amount": "1 tbsp", "substitutes": []}, {"name": "Blueberries", "amount": "1/2 cup", "substitutes": ["Raspberries"]}]'::jsonb, '["Stir the oats, chia seeds and protein powder together in a jar so the powder does not clump later.", "Pour in the milk and yogurt and mix until no dry pockets remain.", "Fold in the blueberries, seal, and refrigerate at least 6 hours.", "Eat cold straight from the jar, or loosen with a splash of milk if it has set too thick."]'::jsonb, 'Keeps 3 days refrigerated. Add berries the morning of if you want them firm.', 'Best cold. Do not microwave — the yogurt will split.', array['Jar or sealed container'], true),
  ('rc-b2', 'Six-Egg Power Scramble', 'A heavy breakfast for training days. Builds the morning around protein and keeps the carbs slow.', 'Breakfast', array['Build Muscle', 'Gain Weight', 'Build Strength'], array['High Protein', 'Gluten Free'], array['Eggs', 'Dairy'], 5, 10, 1, 'Easy', 620, 48, 28, 36, 6, 540, 2.4, '[{"name": "Whole eggs", "amount": "4", "substitutes": []}, {"name": "Egg whites", "amount": "4", "substitutes": []}, {"name": "Spinach", "amount": "2 cups", "substitutes": []}, {"name": "Cherry tomatoes", "amount": "1/2 cup", "substitutes": []}, {"name": "Feta", "amount": "30g", "substitutes": ["Cheddar", "Goat cheese"]}, {"name": "Olive oil", "amount": "1 tsp", "substitutes": []}, {"name": "Sourdough toast", "amount": "1 slice", "substitutes": ["Gluten-free bread"]}]'::jsonb, '["Warm the oil in a non-stick pan over medium-low heat. Low and slow is what keeps eggs soft.", "Wilt the spinach and tomatoes for about two minutes, then push them to one side.", "Beat the eggs and whites together and pour them in. Stir slowly and constantly.", "Pull the pan off the heat while the eggs still look slightly underdone — they finish on their own.", "Fold through the feta and serve on toast."]'::jsonb, 'Best fresh. Scrambled egg does not hold well overnight.', 'If you must, reheat 30 seconds at half power and stop before it steams.', array['Non-stick pan'], true),
  ('rc-b3', 'Endurance Banana Pancakes', 'Fast carbs and enough protein to stop the mid-morning crash. Built for long training days.', 'Breakfast', array['Improve Endurance', 'Improve Overall Fitness', 'Gain Weight'], array['High Protein', 'Vegetarian'], array['Eggs', 'Dairy', 'Gluten'], 10, 12, 2, 'Medium', 480, 28, 68, 11, 7, 320, 1.6, '[{"name": "Banana, ripe", "amount": "2", "substitutes": []}, {"name": "Oat flour", "amount": "1 cup", "substitutes": ["Blended rolled oats"]}, {"name": "Eggs", "amount": "2", "substitutes": []}, {"name": "Greek yogurt", "amount": "1/2 cup", "substitutes": []}, {"name": "Baking powder", "amount": "1 tsp", "substitutes": []}, {"name": "Honey", "amount": "1 tbsp", "substitutes": ["Maple syrup"]}, {"name": "Cinnamon", "amount": "1/2 tsp", "substitutes": []}]'::jsonb, '["Mash the bananas until almost smooth — a few lumps are fine and add texture.", "Whisk in the eggs and yogurt, then fold in the oat flour, baking powder and cinnamon.", "Rest the batter 5 minutes. This is what makes them rise properly.", "Cook on a medium pan, roughly 2 minutes a side. Flip once the surface bubbles hold their shape.", "Finish with honey."]'::jsonb, 'Refrigerate up to 3 days, or freeze flat between sheets of baking paper.', 'Toaster for one minute brings back the edges better than a microwave.', array['Non-stick pan', 'Mixing bowl'], true),
  ('rc-b4', 'Lean Veggie Omelette', 'High volume, low calorie. Fills a plate for under 300 calories when you are cutting.', 'Breakfast', array['Lose Weight', 'Improve Health', 'General Wellness'], array['High Protein', 'Low Carb', 'Gluten Free'], array['Eggs'], 8, 8, 1, 'Easy', 280, 30, 12, 13, 5, 420, 1.9, '[{"name": "Egg whites", "amount": "6", "substitutes": []}, {"name": "Whole egg", "amount": "1", "substitutes": []}, {"name": "Mushrooms", "amount": "1 cup", "substitutes": []}, {"name": "Bell pepper", "amount": "1/2", "substitutes": []}, {"name": "Onion", "amount": "1/4", "substitutes": []}, {"name": "Spinach", "amount": "2 cups", "substitutes": []}, {"name": "Olive oil spray", "amount": "2 sprays", "substitutes": []}]'::jsonb, '["Dice the vegetables small so they cook through before the eggs set.", "Dry-fry the mushrooms first until they release their water and it evaporates — this is where the flavour comes from.", "Add the rest of the vegetables and soften for 3 minutes.", "Pour over the beaten eggs, cover, and cook on low until just set.", "Fold and slide onto the plate."]'::jsonb, 'Keeps 2 days refrigerated.', 'Reheat gently, covered, 45 seconds.', array['Non-stick pan with lid'], true),
  ('rc-l1', 'Grilled Chicken Power Bowl', 'The default lunch. Lean protein, slow carbs and enough volume to actually feel full.', 'Lunch', array['Build Muscle', 'Lose Weight', 'Improve Overall Fitness'], array['High Protein', 'Gluten Free', 'Dairy Free'], '{}', 15, 20, 2, 'Easy', 540, 52, 48, 16, 9, 480, 3.2, '[{"name": "Chicken breast", "amount": "300g", "substitutes": ["Turkey breast", "Firm tofu"]}, {"name": "Brown rice, dry", "amount": "3/4 cup", "substitutes": ["Quinoa"]}, {"name": "Broccoli", "amount": "2 cups", "substitutes": []}, {"name": "Avocado", "amount": "1/2", "substitutes": []}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Lemon", "amount": "1", "substitutes": []}, {"name": "Paprika", "amount": "1 tsp", "substitutes": []}, {"name": "Garlic powder", "amount": "1 tsp", "substitutes": []}]'::jsonb, '["Start the rice first — everything else finishes faster than it does.", "Season the chicken with paprika, garlic, salt and pepper.", "Grill 6-7 minutes a side over medium heat. Rest it 5 minutes before slicing or the juice runs out.", "Steam the broccoli 4 minutes so it keeps some bite.", "Build the bowl, add sliced avocado, and finish with olive oil and a hard squeeze of lemon."]'::jsonb, 'Keeps 4 days. Store the avocado separately and slice it fresh.', 'Microwave 2 minutes, stirring once. Add a splash of water to stop the rice drying.', array['Grill pan', 'Saucepan'], true),
  ('rc-l2', 'Tuna and White Bean Salad', 'No cooking at all. Ready in five minutes and holds 42g of protein.', 'Lunch', array['Lose Weight', 'Improve Health', 'General Wellness'], array['High Protein', 'Gluten Free', 'Dairy Free'], array['Fish'], 8, 0, 2, 'Easy', 390, 42, 34, 10, 11, 620, 2.1, '[{"name": "Tuna in water, drained", "amount": "2 cans", "substitutes": ["Tinned salmon", "Chickpeas"]}, {"name": "Cannellini beans", "amount": "1 can", "substitutes": []}, {"name": "Red onion", "amount": "1/2", "substitutes": []}, {"name": "Cherry tomatoes", "amount": "1 cup", "substitutes": []}, {"name": "Rocket", "amount": "2 cups", "substitutes": ["Spinach"]}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Red wine vinegar", "amount": "1 tbsp", "substitutes": []}]'::jsonb, '["Rinse the beans properly — it removes the tinny taste and a good amount of the sodium.", "Slice the onion thin and sit it in the vinegar for 5 minutes to take the raw edge off.", "Fold everything together gently so the tuna stays in flakes rather than turning to paste.", "Dress with the oil, season, and serve on the rocket."]'::jsonb, 'Keeps 2 days. Dress only the portion you are eating.', 'Serve cold — no reheating needed.', array['Mixing bowl'], true),
  ('rc-l3', 'Turkey and Avocado Wrap', 'A lunch you can eat with one hand between meetings, without it being junk.', 'Lunch', array['Lose Weight', 'Improve Overall Fitness', 'General Wellness'], array['High Protein'], array['Gluten', 'Dairy'], 10, 0, 1, 'Easy', 450, 38, 40, 16, 8, 780, 2.6, '[{"name": "Whole wheat tortilla", "amount": "1 large", "substitutes": ["Gluten-free wrap", "Lettuce leaves"]}, {"name": "Turkey breast, sliced", "amount": "150g", "substitutes": ["Chicken breast"]}, {"name": "Avocado", "amount": "1/2", "substitutes": []}, {"name": "Baby spinach", "amount": "1 cup", "substitutes": []}, {"name": "Tomato", "amount": "1", "substitutes": []}, {"name": "Greek yogurt", "amount": "2 tbsp", "substitutes": ["Hummus"]}, {"name": "Dijon mustard", "amount": "1 tsp", "substitutes": []}]'::jsonb, '["Warm the tortilla for 15 seconds so it folds without cracking.", "Mix the yogurt and mustard and spread it to the edges, leaving a clear border.", "Layer spinach first — it acts as a barrier and keeps the wrap from going soggy.", "Add the turkey, sliced tomato and mashed avocado, keeping the filling in a line rather than a pile.", "Fold the sides in, roll tight, and cut on the diagonal."]'::jsonb, 'Best eaten within a few hours. Wrap tightly in foil if packing.', 'Serve cold.', '{}', true),
  ('rc-l4', 'Salmon Quinoa Salad', 'Omega-3s and complete protein. Good on recovery days when you want food that works on you.', 'Lunch', array['Improve Health', 'Improve Endurance', 'General Wellness'], array['High Protein', 'Gluten Free', 'Dairy Free'], array['Fish'], 12, 18, 2, 'Medium', 520, 40, 42, 20, 7, 390, 4.5, '[{"name": "Salmon fillet", "amount": "280g", "substitutes": ["Trout", "Mackerel"]}, {"name": "Quinoa, dry", "amount": "3/4 cup", "substitutes": []}, {"name": "Cucumber", "amount": "1", "substitutes": []}, {"name": "Cherry tomatoes", "amount": "1 cup", "substitutes": []}, {"name": "Red onion", "amount": "1/4", "substitutes": []}, {"name": "Lemon", "amount": "1", "substitutes": []}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Fresh dill", "amount": "2 tbsp", "substitutes": []}]'::jsonb, '["Rinse the quinoa under cold water first — unrinsed quinoa tastes bitter.", "Simmer it in twice its volume of water for 15 minutes, then let it steam off the heat for 5.", "Season the salmon and pan-sear skin-side down for 4 minutes, then 2 on the flesh side.", "Let the quinoa cool to room temperature before combining, or it will wilt everything.", "Flake the salmon through, add the vegetables, and dress with lemon, oil and dill."]'::jsonb, 'Keeps 3 days refrigerated.', 'Good cold. If reheating, warm the quinoa only and add the salmon after.', array['Saucepan', 'Non-stick pan'], true),
  ('rc-d1', 'Steak and Sweet Potato', 'The classic strength dinner. Iron, creatine and enough carbs to refill after a heavy session.', 'Dinner', array['Build Strength', 'Build Muscle', 'Gain Weight'], array['High Protein', 'Gluten Free', 'Dairy Free'], '{}', 10, 35, 2, 'Medium', 680, 56, 52, 26, 8, 520, 5.8, '[{"name": "Sirloin steak", "amount": "350g", "substitutes": ["Rump", "Flank"]}, {"name": "Sweet potato", "amount": "2 medium", "substitutes": []}, {"name": "Asparagus", "amount": "1 bunch", "substitutes": ["Green beans"]}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Garlic", "amount": "3 cloves", "substitutes": []}, {"name": "Rosemary", "amount": "2 sprigs", "substitutes": []}]'::jsonb, '["Take the steak out of the fridge 30 minutes before cooking. Cold meat cooks unevenly.", "Roast the sweet potato wedges at 200C for 30 minutes, turning once.", "Get the pan properly hot before the steak goes in — you want a crust, not a grey steam.", "Sear 3-4 minutes a side for medium-rare, adding garlic and rosemary for the last minute.", "Rest the steak 8 minutes. This matters more than anything else you do to it.", "Griddle the asparagus while the steak rests, then slice against the grain."]'::jsonb, 'Keeps 3 days. Slice only what you are eating.', 'Reheat low and brief — steak overcooks instantly on reheat. Better eaten cold in a salad.', array['Oven', 'Heavy pan'], true),
  ('rc-d2', 'Baked Cod with Vegetables', 'Very lean, very light, and still a proper dinner. Good the night before a weigh-in.', 'Dinner', array['Lose Weight', 'Improve Health', 'General Wellness'], array['High Protein', 'Low Carb', 'Gluten Free', 'Dairy Free'], array['Fish'], 12, 22, 2, 'Easy', 340, 44, 20, 9, 7, 410, 4.2, '[{"name": "Cod fillet", "amount": "350g", "substitutes": ["Haddock", "Pollock"]}, {"name": "Courgette", "amount": "1", "substitutes": []}, {"name": "Bell peppers", "amount": "2", "substitutes": []}, {"name": "Cherry tomatoes", "amount": "1 cup", "substitutes": []}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Lemon", "amount": "1", "substitutes": []}, {"name": "Oregano", "amount": "1 tsp", "substitutes": []}, {"name": "Garlic", "amount": "2 cloves", "substitutes": []}]'::jsonb, '["Heat the oven to 200C.", "Toss the chopped vegetables with oil, garlic and oregano and spread them in a single layer. Crowding the tray steams them.", "Roast 12 minutes on their own to get a head start.", "Lay the cod on top, season, and return for 10-12 minutes until it flakes with light pressure.", "Squeeze lemon over everything as it comes out of the oven."]'::jsonb, 'Keeps 2 days. White fish degrades faster than oily fish.', 'Reheat covered at 160C for 8 minutes rather than microwaving.', array['Oven', 'Roasting tray'], true),
  ('rc-d3', 'Beef and Broccoli Stir Fry', 'Faster than ordering in. One pan, twelve minutes, 48g of protein.', 'Dinner', array['Build Muscle', 'Build Strength', 'Improve Overall Fitness'], array['High Protein', 'Dairy Free'], array['Soy', 'Gluten'], 15, 12, 2, 'Medium', 590, 48, 54, 20, 6, 890, 4.1, '[{"name": "Beef strips", "amount": "350g", "substitutes": ["Chicken thigh", "Tempeh"]}, {"name": "Broccoli", "amount": "3 cups", "substitutes": []}, {"name": "Jasmine rice, dry", "amount": "3/4 cup", "substitutes": []}, {"name": "Soy sauce", "amount": "3 tbsp", "substitutes": ["Tamari"]}, {"name": "Garlic", "amount": "3 cloves", "substitutes": []}, {"name": "Ginger", "amount": "1 tbsp", "substitutes": []}, {"name": "Sesame oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Cornflour", "amount": "1 tsp", "substitutes": []}]'::jsonb, '["Start the rice before anything else.", "Toss the beef in the cornflour — it holds the sauce and keeps the meat tender.", "Get the pan very hot. Sear the beef in two batches; one crowded batch will stew.", "Set the beef aside, then stir-fry the broccoli with garlic and ginger for 3 minutes with a splash of water to steam it.", "Return the beef, add soy and sesame oil, and toss for one final minute."]'::jsonb, 'Keeps 3 days refrigerated.', 'Microwave 2 minutes stirring halfway, or 3 minutes in a hot pan.', array['Wok or large pan', 'Saucepan'], true),
  ('rc-d4', 'Chicken Pasta Primavera', 'Carb-loading that does not feel like a chore. Good the night before a long effort.', 'Dinner', array['Improve Endurance', 'Gain Weight', 'Improve Overall Fitness'], array['High Protein'], array['Gluten', 'Dairy'], 12, 20, 2, 'Easy', 650, 46, 78, 16, 9, 560, 3.4, '[{"name": "Chicken breast", "amount": "280g", "substitutes": []}, {"name": "Wholewheat pasta, dry", "amount": "160g", "substitutes": ["Gluten-free pasta"]}, {"name": "Courgette", "amount": "1", "substitutes": []}, {"name": "Bell pepper", "amount": "1", "substitutes": []}, {"name": "Cherry tomatoes", "amount": "1 cup", "substitutes": []}, {"name": "Parmesan", "amount": "30g", "substitutes": []}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Basil", "amount": "handful", "substitutes": []}]'::jsonb, '["Salt the pasta water properly — it is the only chance to season the pasta itself.", "Cook the pasta to one minute short of the packet time and keep a cup of the water.", "Pan-fry the diced chicken until golden, then set aside.", "Soften the vegetables in the same pan so they pick up the fond.", "Return everything with a splash of the pasta water and toss hard — the starch is what makes it a sauce.", "Finish off the heat with parmesan and torn basil."]'::jsonb, 'Keeps 3 days.', 'Add a splash of water before reheating or it will be dry.', array['Large pot', 'Frying pan'], true),
  ('rc-s1', 'Post-Workout Recovery Shake', 'Drink it inside the hour after training. Fast carbs and 40g of protein.', 'Smoothies', array['Build Muscle', 'Improve Endurance', 'Build Strength'], array['High Protein', 'Vegetarian'], array['Dairy'], 5, 0, 1, 'Easy', 420, 40, 52, 6, 5, 220, 2.3, '[{"name": "Whey protein", "amount": "1.5 scoops", "substitutes": ["Plant protein"]}, {"name": "Banana", "amount": "1", "substitutes": []}, {"name": "Milk", "amount": "1 cup", "substitutes": ["Almond milk"]}, {"name": "Frozen berries", "amount": "1 cup", "substitutes": []}, {"name": "Honey", "amount": "1 tsp", "substitutes": []}, {"name": "Ice", "amount": "4 cubes", "substitutes": []}]'::jsonb, '["Liquid into the blender first — it stops the powder packing against the blades.", "Add the protein, then the fruit and ice on top.", "Blend 45 seconds until there is no grit left.", "Drink straight away; it separates within about ten minutes."]'::jsonb, 'Make fresh. Protein shakes do not hold.', 'Not applicable.', array['Blender'], true),
  ('rc-s2', 'Green Performance Smoothie', 'Micronutrients without eating a bowl of leaves. Tastes of mango, not spinach.', 'Smoothies', array['Improve Health', 'General Wellness', 'Lose Weight'], array['Vegan', 'Dairy Free', 'Gluten Free'], '{}', 6, 0, 1, 'Easy', 290, 12, 48, 7, 9, 95, 2.0, '[{"name": "Spinach", "amount": "2 cups", "substitutes": []}, {"name": "Mango, frozen", "amount": "1 cup", "substitutes": []}, {"name": "Banana", "amount": "1", "substitutes": []}, {"name": "Almond milk", "amount": "1 cup", "substitutes": ["Oat milk"]}, {"name": "Chia seeds", "amount": "1 tbsp", "substitutes": []}, {"name": "Plant protein, vanilla", "amount": "1 scoop", "substitutes": []}, {"name": "Lime", "amount": "1/2", "substitutes": []}]'::jsonb, '["Blend the spinach with the almond milk alone first, until completely smooth.", "Add the frozen mango, banana, protein and chia.", "Blend another 30 seconds. Loosen with more milk if the blender is struggling.", "Finish with lime — it lifts the whole thing and kills any grassy note."]'::jsonb, 'Best fresh. Will hold 12 hours sealed and full to the top.', 'Shake hard before drinking if it has settled.', array['Blender'], true),
  ('rc-s3', 'Mass Gainer Shake', 'A thousand calories you can drink. For when eating enough is the hard part.', 'Smoothies', array['Gain Weight', 'Build Muscle'], array['High Protein', 'Vegetarian'], array['Dairy', 'Nuts'], 5, 0, 1, 'Easy', 980, 55, 110, 34, 12, 310, 3.1, '[{"name": "Whole milk", "amount": "1.5 cups", "substitutes": ["Oat milk"]}, {"name": "Whey protein", "amount": "2 scoops", "substitutes": []}, {"name": "Rolled oats", "amount": "1/2 cup", "substitutes": []}, {"name": "Peanut butter", "amount": "2 tbsp", "substitutes": ["Almond butter"]}, {"name": "Banana", "amount": "2", "substitutes": []}, {"name": "Honey", "amount": "1 tbsp", "substitutes": []}, {"name": "Greek yogurt", "amount": "1/2 cup", "substitutes": []}]'::jsonb, '["Blend the oats dry first into a rough flour so the shake is not gritty.", "Add the milk, yogurt and protein and blend smooth.", "Add the bananas, peanut butter and honey and blend another 30 seconds.", "If it is too thick to drink easily, add milk rather than water — you want the calories."]'::jsonb, 'Keeps 24 hours refrigerated, sealed.', 'Shake well; it thickens as the oats absorb.', array['Blender'], true),
  ('rc-s4', 'Tart Cherry Sleep Shake', 'Evening recovery drink. Slow protein and tart cherry for overnight repair.', 'Smoothies', array['Improve Endurance', 'Improve Health', 'General Wellness'], array['High Protein', 'Vegetarian'], array['Dairy'], 4, 0, 1, 'Easy', 310, 32, 30, 8, 4, 180, 2.7, '[{"name": "Casein protein", "amount": "1 scoop", "substitutes": ["Greek yogurt"]}, {"name": "Tart cherry juice", "amount": "1 cup", "substitutes": []}, {"name": "Milk", "amount": "1/2 cup", "substitutes": []}, {"name": "Frozen cherries", "amount": "1/2 cup", "substitutes": []}, {"name": "Cinnamon", "amount": "1/4 tsp", "substitutes": []}]'::jsonb, '["Blend everything for 30 seconds.", "Casein thickens as it stands, so drink it within a few minutes or add more milk.", "Have it about an hour before bed."]'::jsonb, 'Make fresh.', 'Not applicable.', array['Blender'], true),
  ('rc-n1', 'No-Bake Protein Balls', 'Twelve at a time, 10g of protein each. Stops the vending machine decision.', 'Snacks', array['Build Muscle', 'Improve Overall Fitness', 'Gain Weight'], array['High Protein', 'Vegetarian'], array['Nuts', 'Dairy'], 15, 0, 12, 'Easy', 150, 10, 14, 7, 3, 65, 0.6, '[{"name": "Rolled oats", "amount": "1.5 cups", "substitutes": []}, {"name": "Peanut butter", "amount": "1/2 cup", "substitutes": ["Almond butter", "Sunflower seed butter"]}, {"name": "Whey protein", "amount": "2 scoops", "substitutes": []}, {"name": "Honey", "amount": "1/3 cup", "substitutes": ["Maple syrup"]}, {"name": "Dark chocolate chips", "amount": "1/4 cup", "substitutes": []}, {"name": "Chia seeds", "amount": "2 tbsp", "substitutes": []}]'::jsonb, '["Mix the dry ingredients first so the protein powder distributes evenly.", "Work in the peanut butter and honey with a spoon, then your hands. It will look too dry before it suddenly comes together.", "If it stays crumbly add honey a teaspoon at a time; if it is sticky add oats.", "Roll into twelve balls and chill 30 minutes to firm up."]'::jsonb, 'Two weeks refrigerated, three months frozen.', 'Eat cold.', array['Mixing bowl'], true),
  ('rc-n2', 'Cottage Cheese and Berries', 'Thirty seconds of work for 25g of slow protein. The most efficient snack here.', 'Snacks', array['Lose Weight', 'Build Muscle', 'Improve Health'], array['High Protein', 'Vegetarian', 'Gluten Free', 'Low Carb'], array['Dairy'], 3, 0, 1, 'Easy', 220, 25, 18, 5, 3, 480, 1.4, '[{"name": "Cottage cheese", "amount": "1 cup", "substitutes": []}, {"name": "Mixed berries", "amount": "3/4 cup", "substitutes": []}, {"name": "Almonds, flaked", "amount": "1 tbsp", "substitutes": ["Walnuts"]}, {"name": "Cinnamon", "amount": "pinch", "substitutes": []}]'::jsonb, '["Spoon the cottage cheese into a bowl.", "Top with the berries and almonds and dust with cinnamon.", "If the texture puts you off, blend the cottage cheese alone for 20 seconds first — it turns silky."]'::jsonb, 'Assemble fresh; keeps 2 days if you must.', 'Eat cold.', '{}', true),
  ('rc-n3', 'Spiced Roasted Chickpeas', 'Crunchy, savoury and high fibre. Scratches the crisps itch for a fraction of the calories.', 'Snacks', array['Lose Weight', 'Improve Health', 'General Wellness'], array['Vegan', 'Gluten Free', 'Dairy Free'], '{}', 5, 35, 4, 'Easy', 180, 9, 24, 6, 8, 290, 0.7, '[{"name": "Chickpeas", "amount": "2 cans", "substitutes": []}, {"name": "Olive oil", "amount": "1 tbsp", "substitutes": []}, {"name": "Smoked paprika", "amount": "1 tsp", "substitutes": []}, {"name": "Cumin", "amount": "1 tsp", "substitutes": []}, {"name": "Garlic powder", "amount": "1/2 tsp", "substitutes": []}, {"name": "Salt", "amount": "1/2 tsp", "substitutes": []}]'::jsonb, '["Drain, rinse and then dry the chickpeas thoroughly in a towel. Any moisture left means they steam instead of crisping.", "Toss with the oil and spices.", "Spread on a tray in one layer and roast at 200C for 30-35 minutes, shaking twice.", "They crisp further as they cool, so judge them cold, not hot."]'::jsonb, 'Keeps 4 days in a jar left slightly open. Sealed airtight they go soft.', 'Five minutes in a hot oven brings the crunch back.', array['Oven', 'Baking tray'], true),
  ('rc-n4', 'Greek Yogurt Parfait', 'Layered so it looks like a dessert and lands like a protein snack.', 'Snacks', array['Build Muscle', 'Lose Weight', 'General Wellness'], array['High Protein', 'Vegetarian'], array['Dairy', 'Nuts', 'Gluten'], 5, 0, 1, 'Easy', 310, 24, 36, 8, 5, 120, 1.7, '[{"name": "Greek yogurt", "amount": "1 cup", "substitutes": []}, {"name": "Granola", "amount": "1/3 cup", "substitutes": ["Toasted oats"]}, {"name": "Strawberries", "amount": "1/2 cup", "substitutes": []}, {"name": "Honey", "amount": "1 tsp", "substitutes": []}, {"name": "Walnuts", "amount": "1 tbsp", "substitutes": []}]'::jsonb, '["Layer half the yogurt, then fruit, then granola, and repeat.", "Add the granola only when you are about to eat it, or it goes soft.", "Finish with honey and walnuts."]'::jsonb, 'Assemble fresh.', 'Eat cold.', array['Glass or jar'], true),
  ('rc-m1', 'Batch Chicken and Rice (5 Meals)', 'One Sunday session covers the working week. Five containers, 52g of protein each.', 'Meal Prep', array['Build Muscle', 'Improve Overall Fitness', 'Build Strength'], array['High Protein', 'Gluten Free', 'Dairy Free'], '{}', 20, 45, 5, 'Medium', 560, 52, 56, 14, 7, 460, 2.8, '[{"name": "Chicken breast", "amount": "1.2kg", "substitutes": []}, {"name": "Brown rice, dry", "amount": "2.5 cups", "substitutes": []}, {"name": "Broccoli", "amount": "4 cups", "substitutes": []}, {"name": "Carrots", "amount": "4", "substitutes": []}, {"name": "Olive oil", "amount": "2 tbsp", "substitutes": []}, {"name": "Paprika", "amount": "1 tbsp", "substitutes": []}, {"name": "Garlic powder", "amount": "1 tbsp", "substitutes": []}, {"name": "Black pepper", "amount": "2 tsp", "substitutes": []}]'::jsonb, '["Heat the oven to 200C and start the rice — it takes the longest.", "Season the chicken generously. Under-seasoning is the usual reason prepped food is grim by Wednesday.", "Roast the chicken 22-25 minutes until it reaches 74C internally. Do not guess; dry chicken ruins the week.", "Roast the vegetables on a second tray for 20 minutes.", "Let everything cool fully before the lids go on, or condensation will make the rice wet.", "Divide across five containers and refrigerate."]'::jsonb, 'Four days refrigerated. Freeze containers four and five on day one and move them to the fridge the night before.', 'Microwave 2-3 minutes with a splash of water and the lid ajar.', array['Oven', 'Two baking trays', 'Rice cooker or saucepan', '5 containers'], true),
  ('rc-m2', 'Turkey Chilli (6 Portions)', 'Freezes perfectly and tastes better on day two. Lean protein with real fibre.', 'Meal Prep', array['Lose Weight', 'Build Muscle', 'Improve Health'], array['High Protein', 'Gluten Free', 'Dairy Free'], '{}', 15, 50, 6, 'Medium', 420, 38, 42, 11, 13, 640, 2.2, '[{"name": "Turkey mince, 5%", "amount": "900g", "substitutes": ["Chicken mince", "Lentils"]}, {"name": "Kidney beans", "amount": "2 cans", "substitutes": []}, {"name": "Chopped tomatoes", "amount": "2 cans", "substitutes": []}, {"name": "Onion", "amount": "2", "substitutes": []}, {"name": "Bell peppers", "amount": "2", "substitutes": []}, {"name": "Garlic", "amount": "4 cloves", "substitutes": []}, {"name": "Chilli powder", "amount": "2 tbsp", "substitutes": []}, {"name": "Cumin", "amount": "1 tbsp", "substitutes": []}, {"name": "Beef stock", "amount": "1 cup", "substitutes": []}]'::jsonb, '["Brown the mince hard in batches and do not stir it too early — the browning is the flavour.", "Soften the onion, pepper and garlic in the same pot.", "Return the meat, add the spices, and cook them out for a full minute before any liquid goes in.", "Add the tomatoes, beans and stock, then simmer uncovered for 40 minutes.", "Taste and season at the end, not the start — it reduces and concentrates."]'::jsonb, 'Five days refrigerated, three months frozen. It genuinely improves overnight.', 'Reheat on the hob with a splash of water, or microwave 3 minutes stirring once.', array['Large heavy pot', '6 containers'], true),
  ('rc-m3', 'Overnight Egg Muffins (12)', 'Grab two on the way out. Twelve breakfasts from twenty minutes of work.', 'Meal Prep', array['Lose Weight', 'Build Muscle', 'Improve Overall Fitness'], array['High Protein', 'Gluten Free', 'Low Carb'], array['Eggs', 'Dairy'], 15, 25, 12, 'Easy', 110, 11, 3, 6, 1, 210, 0.55, '[{"name": "Eggs", "amount": "12", "substitutes": []}, {"name": "Spinach", "amount": "3 cups", "substitutes": []}, {"name": "Bell pepper", "amount": "1", "substitutes": []}, {"name": "Mushrooms", "amount": "1 cup", "substitutes": []}, {"name": "Cheddar", "amount": "60g", "substitutes": ["Feta"]}, {"name": "Olive oil spray", "amount": "as needed", "substitutes": []}]'::jsonb, '["Heat the oven to 180C and grease a 12-hole muffin tin properly — egg welds itself to metal.", "Cook the mushrooms and pepper off first to drive out their water, or the muffins turn out wet.", "Beat the eggs with salt and pepper and stir through the cooled vegetables and cheese.", "Fill each hole about three-quarters full; they rise and then settle.", "Bake 22-25 minutes until just set in the middle.", "Cool 5 minutes in the tin before easing them out."]'::jsonb, 'Four days refrigerated, two months frozen.', 'Microwave 30 seconds from the fridge, 60 from frozen.', array['Oven', '12-hole muffin tin'], true),
  ('rc-m4', 'Endurance Pasta Bake (5 Portions)', 'Bulk carbohydrate for heavy training weeks, with enough protein to be a real meal.', 'Meal Prep', array['Improve Endurance', 'Gain Weight', 'Improve Overall Fitness'], array['High Protein'], array['Gluten', 'Dairy'], 20, 40, 5, 'Medium', 620, 42, 82, 14, 10, 680, 2.5, '[{"name": "Wholewheat pasta, dry", "amount": "500g", "substitutes": ["Gluten-free pasta"]}, {"name": "Chicken breast", "amount": "700g", "substitutes": []}, {"name": "Passata", "amount": "700g", "substitutes": []}, {"name": "Mozzarella", "amount": "150g", "substitutes": []}, {"name": "Onion", "amount": "2", "substitutes": []}, {"name": "Garlic", "amount": "4 cloves", "substitutes": []}, {"name": "Italian herbs", "amount": "2 tbsp", "substitutes": []}, {"name": "Spinach", "amount": "4 cups", "substitutes": []}]'::jsonb, '["Boil the pasta three minutes short of the packet time — it keeps cooking in the oven.", "Brown the diced chicken with the onion and garlic.", "Add the passata and herbs and simmer 10 minutes to thicken.", "Wilt the spinach through the sauce, then fold in the drained pasta.", "Transfer to a baking dish, top with mozzarella, and bake at 190C for 20 minutes.", "Let it stand 10 minutes before portioning or it will not hold its shape."]'::jsonb, 'Four days refrigerated, two months frozen in portions.', 'Microwave 3 minutes covered, or 20 minutes at 180C from chilled.', array['Oven', 'Large pot', 'Baking dish', '5 containers'], true)
